import './App.css';

import firebase from 'firebase/compat/app';
import 'firebase/compat/auth';

import { useAuthState } from 'react-firebase-hooks/auth';

firebase.initializeApp({
  apiKey: "AIzaSyC-faolhhaTx3b4s8sbSEpBTLVMSB04Upg",
  authDomain: "mypuzzlediary.firebaseapp.com",
  projectId: "mypuzzlediary",
  storageBucket: "mypuzzlediary.appspot.com",
  messagingSenderId: "325620729234",
  appId: "1:325620729234:web:a03097ec332f2283f42d4b"
});

const auth = firebase.auth();


function App() {

  const [user] = useAuthState(auth);

  return (
    <div className="App">
        <header>
          <p>Puzzle Diary</p>
        </header>
        <div>
          { user ? <PuzzleBoard /> : <PuzzleBoard /> }
        </div>
    </div>
  );
}

function SignIn() {
  const signInWithGoogle = () => {
    const provider = new firebase.auth.GoogleAuthProvider();
    auth.signInWithPopup(provider);
  }


  return (
    <button onClick={signInWithGoogle}>Sign in with Google</button>
  );
}

function SignOut() {
  return auth.currentUser && (
    <button onClick={() => auth.signOut()}>Sign Out</button>
  )
}

const PuzzleCard = () => {
  return (
    <div className='Puzzle'>
      <p>Game Title</p>
      <img src='' alt='IMAGE'/>
    </div>
  )
}

function PuzzleBoard() {
  return (
    <PuzzleCard />
  );
}

export default App;
